const e = $input.first().json;
const wf = e.workflow || {};
const ex = e.execution || {};
const msg = (ex.error && ex.error.message) || 'Unknown error';
const node = ex.lastNodeExecuted || 'unknown node';

// Throttle: same problem at most once every 10 minutes, so a bad night does not flood the inbox.
const sd = $getWorkflowStaticData('global');
sd.last = sd.last || {};
const key = [wf.name, node, msg.slice(0, 80)].join('|');
const t = Date.now();
if (sd.last[key] && t - sd.last[key] < 10 * 60 * 1000) return [];
sd.last[key] = t;
for (const k of Object.keys(sd.last)) if (t - sd.last[k] > 3600 * 1000) delete sd.last[k];

const d = DateTime.now().setZone('Africa/Addis_Ababa').setLocale('en');
const toEth = (h) => ((h - 6 + 12) % 12) || 12;
const when = d.toFormat('cccc, LLLL d, h:mm:ss a') + ' (' + toEth(d.hour) + ':' + d.toFormat('mm:ss') + ' local)';
const esc = (v) => String(v == null ? '' : v).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const html = '<div style="font-family:Arial,sans-serif;max-width:560px;color:#222">' +
  '<h2 style="color:#b00020;margin:0 0 8px">Workflow error</h2>' +
  '<p><b>Workflow:</b> ' + esc(wf.name) + '</p>' +
  '<p><b>Failed at:</b> ' + esc(node) + '</p>' +
  '<p><b>Message:</b> ' + esc(msg) + '</p>' +
  '<p><b>When:</b> ' + esc(when) + '</p>' +
  '<p><b>Execution:</b> ' + esc(ex.id || '-') + (ex.url ? ' - <a href="' + esc(ex.url) + '">open in n8n</a>' : '') + '</p>' +
  '<p style="color:#666">Repeats of this same error are muted for 10 minutes.</p></div>';
return [{ json: { subject: '[ALERT] ' + wf.name + ' failed at ' + node, html } }];
